function makePrefixer(prefix) {
  return function (text) {
    return `${prefix} ${text}`;
  };
}
function prefixText(prefix, text) {
  return makePrefixer(prefix)(text);
}

function makeCounter(start) {
  let count = start;
  return function () {
    count += 1;
    return count;
  };
}
function countTwice(start) {
  const count = makeCounter(start);
  count();
  return count();
}
